const TERM = { title:'TB8205', sub:'as M8208TR1.CDR (no M8207 terminal art in the archive)', left:['INPUT +','INPUT −','IN SH','OUT 1 + (DIR)','OUT 1 − (DIR)','OUT 2 +','OUT 2 −','GND'], right:[], foot:'OUTPUT 1: 0 Ω (R32/R34) · OUTPUT 2: 30 Ω 1 W per leg (R33/R35)' };

/* ---------------- model ---------------- */
const MAXOUT=30, VCA_K=0.0061, DT=0.0005, N=2000;
const LIM_ATT = 220*2.2e-6, LIM_REL = 1e6*2.2e-6;     // R42 220 / R43 1M with C33 2u2 (XSM8207): 0.48 ms attack, 2.2 s release
const D = {};
function reset(){ Object.assign(D,{ inDbu:2, burst:10, f:1000, sens:1/3, cth:0.5, slope:0.4, lth:0.5, makeup:0.25, crel:0.5, offset:0.5, sym:0.5, lf:0.5, hf:0.5, comp:true, lim:true, board:'M8207', sel:null, rsel:null, load:600, ev:[], inserted:true }); }
const sensDb=()=>-6+18*D.sens, cThr=()=>-10+20*D.cth, ratio=()=>1+9*D.slope, lThr=()=>4+16*D.lth, mkDb=()=>12*D.makeup, cRel=()=>0.05+0.95*D.crel;   // trim laws inferred
const progAt = t => D.inDbu + ((t>=0.25&&t<0.6)? D.burst : 0);           // the test programme: a tone burst
let SIMC=null, SIMKEY='';
function run(){ const key=JSON.stringify([D.inDbu,D.burst,D.sens,D.cth,D.slope,D.lth,D.makeup,D.crel,D.comp,D.lim,D.inserted]); if(key===SIMKEY) return SIMC; SIMKEY=key;
  const det=new Float32Array(N), gr=new Float32Array(N), grc=new Float32Array(N), grl=new Float32Array(N); let ec=(D.inserted?progAt(0):-200)+sensDb(), el=0;
  const aC=1-Math.exp(-DT/0.005), rC=1-Math.exp(-DT/cRel()), aL=1-Math.exp(-DT/LIM_ATT), rL=1-Math.exp(-DT/LIM_REL);
  for(let i=0;i<N;i++){ const x=(D.inserted?progAt(i*DT):-200)+sensDb(); ec += (x>ec? aC : rC)*(x-ec);           // rms-ish detector (U7/U8, CR11 1N5711)
    const gc = D.comp && ec>cThr()? (ec-cThr())*(1-1/ratio()) : 0;
    const post = x - gc; const over = D.lim? Math.max(0, post-lThr()) : 0; el += (over>el? aL : rL)*(over-el);    // limiter peak detector (U6, CR8, C33)
    det[i]=ec; grc[i]=gc; grl[i]=el; gr[i]=gc+el; }
  SIMC={det,gr,grc,grl}; return SIMC; }
const idx = t => clamp(Math.floor(t/DT),0,N-1);
function chain(t){ t=t==null?SIM.t:t; const S=run(), i=idx(t), x=(D.inserted?progAt(t):-200), s=x+sensDb(), out=s-S.gr[i]+mkDb();
  const stages=[{name:'Input (INPUT ±)', db:x, g:null, note:'0 to +8 dBu (F01)'},{name:'U1 + SENSITIVITY R13', db:s, g:sensDb(), max:23, note:'LM833N'},{name:'DBX 2151 (GR element)', db:s-S.gr[i], g:-S.gr[i], max:23, note:'gain reduction '+S.gr[i].toFixed(1)+' dB'},{name:'U3/U4 + MAKE UP R29', db:out, g:mkDb(), max:MAXOUT, note:'NE5534N; OUTPUT 1 (0 Ω)'}];
  return {x,s,gr:S.gr[i],grc:S.grc[i],grl:S.grl[i],det:S.det[i],out,stages,clip:out>MAXOUT,cv:-S.gr[i]*VCA_K}; }

/* ---------------- actions ---------------- */
const NM={sens:'SENSITIVITY R13 5K',cth:'Compressor threshold R56 2K',slope:'SLOPE R68 5K',lth:'Limiter THRESHOLD R48 2K',makeup:'MAKE UP R29 5K',offset:'VCA OFFSET R16 20K',sym:'VCA SYMMETRY R17 50K',lf:'LF DIF R6',hf:'HF DIF C5',crel:'Compressor release'};
const A={
  set(k,v,log){ D[k]=v; D.ev.push({t:SIM.t,name:NM[k].split(' ')[0]}); if(log) act(NM[k]+' adjusted', tr=>{ const c=chain();
    if(k==='sens') tr(`Input stage ${sensDb().toFixed(1)} dB: the detector now sees ${fmtDb(c.s)} before the burst`);
    if(k==='cth') tr(`Compressor threshold ${fmtDb(cThr())} ${inf}: above it the U7/U8 detector (1N5711 CR11) pulls the 2151 down`);
    if(k==='slope') tr(`SLOPE: ratio ${ratio().toFixed(1)} : 1 ${inf} (F01: “SLOPE” in the compressor control)`);
    if(k==='lth') tr(`Limiter THRESHOLD (R48, labelled on XSM8207) ${fmtDb(lThr())} ${inf}: U6 with CR8 1N5711 charges C33 2u2 through R42 220 (0.48 ms) and releases through R43 1M (2.2 s)`);
    if(k==='makeup') tr(`MAKE UP (R29, labelled): +${mkDb().toFixed(1)} dB after the GR element`);
    if(k==='crel') tr(`Compressor release ≈ ${(cRel()*1000).toFixed(0)} ms ${inf}`);
    if(k==='offset'||k==='sym') tr('2151 trims (as on the M8208): OFFSET sets the control-port zero, SYMMETRY nulls even-order distortion');
    tr(`At the playhead: GR ${c.gr.toFixed(1)} dB (compressor ${c.grc.toFixed(1)}, limiter ${c.grl.toFixed(1)}), output ${fmtDb(c.out)}`); }); },
  tog(k){ act((k==='comp'?'Compressor':'Limiter')+' '+(D[k]?'bypassed':'in circuit'), tr=>{ D[k]=!D[k]; tr(`${k==='comp'?'Compressor control':'Limit control'} ${D[k]?'active':'out of circuit (study switch; the card has no such switch '+inf+')'}`); }); },
  part(r){ act('Part '+r, tr=>{ D.sel=r; const p=BRD[D.board].parts.find(q=>q.ref===r); tr(`${r}: ${p&&p.v?p.v:'—'} · ${p?p.pat:''}`); if(ROLE[r]) tr(ROLE[r]); }); },
  rrow(i){ const lab=tbLabel(TERM,i); act('Terminal '+lab, tr=>{ D.rsel=i; tr(/OUT/.test(lab)?`${lab}: ${fmtDb(chain().out)}`:/INPUT/.test(lab)?`${lab}: ${fmtDb(chain().x)}`:lab); }); },
  front(){ act('FRONT PANEL P2 / P3', tr=>{ tr('XSM8207 shows two front-panel connectors, P2 and P3, fed from the U7D (LM837) stage through R78 1K; a gain-reduction indicator is the likely use '+inf); tr(`Gain reduction now ${chain().gr.toFixed(1)} dB`); }); },
  insert(){ act(D.inserted?'Pull the card out':'Slide the card in', tr=>{ D.inserted=!D.inserted; tr(D.inserted?'±22 V on P1 15/S, 13/P; U9 LM317LZ / U10 LM337LZ make ±12 V for the 2151 control':'Silent'); }); },
  reset(){ act('Start over', tr=>{ reset(); tr('A +2 dBu tone with a +10 dB burst from 0.25 s to 0.6 s'); }); },
};
const ROLE={U2:'U2 DBX 2151: the GR (gain-reduction) element',U6:'U6 LM837N: limiter detector and control',U7:'U7 LM837N: compressor rectifier/detector',U8:'U8 LF353N: compressor log/slope stage',R13:'SENSITIVITY 5K',R29:'MAKE UP 5K',R48:'THRESHOLD 2K (limiter)',R56:'2K trim in the U7A rectifier — compressor threshold (inferred)',R60:'OFFSET 2K (detector)',R68:'5K trim at U8B — SLOPE (inferred)',R16:'VCA OFFSET 20K',R17:'VCA SYMMETRY 50K',P2:'FRONT PANEL connector',P3:'FRONT PANEL connector',Q1:'2N3904 (log pair with Q2)',Q2:'2N3904'};

/* ---------------- drawings ---------------- */
function ctl(){ const k=(key,x,y,kind,short,ly)=>({k:key,label:NM[key],short,kind,x,y,ly,get:()=>D[key],set:(v,l)=>A.set(key,v,l)});
  const B=D.board; return [k('sens',0.225,0.33,'multi','SENS',0.85), k('slope',0.6,0.78,'trim','SLOPE',1.25), k('cth',1.925,1.73,'trim','COMP THR',2.3), k('offset',4.15,0.73,'trim','OFFSET',0.2), k('sym',4.8,0.73,'trim','SYM',0.2), k('makeup',6.4,0.73,'trim','MAKE UP',0.2), k('lth',6.675,2.43,'trim','LIM THR',2.0)]; }
function grMeter(){ const c=chain(), w=Math.min(1,c.gr/20); return `<svg viewBox="0 0 280 70" style="width:100%;max-width:280px"><rect x="0" y="0" width="280" height="70" rx="8" fill="#1d1f21"/><text x="10" y="18" font-size="11" fill="#ddd">Gain reduction (P2/P3 indicator, inferred)</text>${Array.from({length:10},(_,i)=>`<rect x="${12+i*26}" y="30" width="22" height="16" rx="2" fill="${i<Math.round(w*10)?(i>6?'#ff5a4a':'#ffb43a'):'#2c332c'}"/>`).join('')}<text x="10" y="62" font-size="10" fill="#aaa">0</text><text x="262" y="62" font-size="10" fill="#aaa">20 dB</text></svg>`; }
function panelHTML(){ const B=BRD[D.board]; B.ctl=ctl(); const c=chain();
  return card(`The card — M8207 (${D.board==='M8207'?'M8207.PCB':'14-278 routed'}) · GR ${c.gr.toFixed(1)} dB`, boardSVG(B,{sel:D.sel})+controlsHTML())+`<div class="grid2"><div>${card('Front edge', handleSVG('M8207', `<g class="hnd" style="cursor:pointer"><title>Click: slide the card ${D.inserted?'out':'in'}</title><rect x="10" y="80" width="60" height="100" fill="transparent"/></g><text x="80" y="140" font-size="11" fill="${D.inserted?'var(--accent)':'var(--warn)'}">${D.inserted?'in the frame':'pulled out'}</text>`))}${card('Front panel P2 / P3', `<div class="fp" style="cursor:pointer">${grMeter()}</div>`)}</div>${card('Rear module (as M8208)', tbSVG(Object.assign(TERM,{sig:l=>/OUT|INPUT/.test(l)?l:null}),{sel:D.rsel}))}</div>`; }
function controlsHTML(){ return `<div class="small" style="display:flex;flex-wrap:wrap;gap:8px 14px;margin-top:8px;align-items:center">
  <label>Programme level <input type="range" data-c="in" min="-10" max="12" value="${D.inDbu}"> <span class="mono">${fmtDb(D.inDbu)}</span></label>
  <label>Burst (0.25–0.6 s) <input type="range" data-c="burst" min="0" max="20" value="${D.burst}"> <span class="mono">+${D.burst} dB</span></label>
  <label>Compressor release <input type="range" data-c="crel" min="0" max="100" value="${Math.round(D.crel*100)}"></label>
  <label><input type="checkbox" data-c="comp" ${D.comp?'checked':''}> compressor</label><label><input type="checkbox" data-c="lim" ${D.lim?'checked':''}> limiter</label>
  <label>Board file <select data-c="board"><option ${D.board==='M8207'?'selected':''}>M8207</option><option ${D.board==='14-278'?'selected':''}>14-278</option></select></label>
  <button data-c="reset">Start over</button></div>`; }
function bind(root){ const B=BRD[D.board]; bindBoard(root,B,r=>A.part(r)); root.querySelectorAll('.rrow').forEach(g=>g.onclick=()=>A.rrow(+g.dataset.i)); root.querySelectorAll('.hnd').forEach(g=>g.onclick=()=>A.insert()); root.querySelectorAll('.fp').forEach(g=>g.onclick=()=>A.front());
  root.querySelectorAll('[data-c]').forEach(e=>{ const c=e.dataset.c; if(c==='reset') e.onclick=()=>A.reset(); else if(c==='in'||c==='burst') e.oninput=()=>{ D[c==='in'?'inDbu':'burst']=+e.value; SIM.refresh(); };
    else if(c==='crel') e.oninput=()=>A.set('crel',+e.value/100,false); else if(c==='comp'||c==='lim') e.onchange=()=>A.tog(c); else if(c==='board') e.onchange=()=>{ D.board=e.value; SIM.refresh(); }; }); }
function stateHTML(){ const c=chain(); return `<table class="kv"><tr><th>Compressor</th><td class="mono">${D.comp?'thr '+fmtDb(cThr())+', '+ratio().toFixed(1)+':1, rel '+(cRel()*1000).toFixed(0)+' ms':'bypassed'} ${inf}</td></tr><tr><th>Limiter</th><td class="mono">${D.lim?'thr '+fmtDb(lThr())+', 0.48 ms / 2.2 s':'bypassed'}</td></tr><tr><th>Detector</th><td class="mono">${fmtDb(c.det)}</td></tr><tr><th>GR now</th><td class="mono">${c.gr.toFixed(1)} dB (comp ${c.grc.toFixed(1)}, lim ${c.grl.toFixed(1)})</td></tr><tr><th>2151 control</th><td class="mono">${(c.cv*1000).toFixed(0)} mV ${inf}</td></tr><tr><th>Output</th><td class="mono">${fmtDb(c.out)} (make-up +${mkDb().toFixed(1)})</td></tr></table>`; }
function lanes(){ const f=D.f, S=run(); return [
  waveLane('Input programme (tone burst)', 44, t=>sineV(t,D.inserted?progAt(t):-200,f), {f, col:SIM.css('--ink2'), level:D.inDbu+D.burst}),
  valueLane('Detector (U7/U8)', 30, t=>S.det[idx(t)], -20, 30, {fmt:v=>fmtDb(v)}),
  valueLane('Gain reduction (2151)', 34, t=>-S.gr[idx(t)], -25, 0, {fmt:v=>v.toFixed(1)+' dB', col:SIM.css('--bad')}),
  valueLane('Limiter part of GR (C33)', 26, t=>-S.grl[idx(t)], -15, 0, {fmt:v=>v.toFixed(1)+' dB', col:SIM.css('--warn')}),
  waveLane('OUTPUT 1 (after MAKE UP)', 46, t=>sineV(t,(D.inserted?progAt(t):-200)+sensDb()-S.gr[idx(t)]+mkDb(),f,MAXOUT), {f, clip:MAXOUT, col:SIM.css('--accent2'), level:D.inDbu+D.burst+sensDb()+mkDb()}),
  eventLane('Your adjustments', ()=>D.ev) ]; }
function secondHTML(){ const S=run(); let mx=0; for(let i=0;i<N;i++) mx=Math.max(mx,S.gr[i]); const tEnd=(()=>{ for(let i=Math.floor(0.6/DT);i<N;i++) if(S.gr[i]<0.5) return i*DT; return null; })();
  return `<table class="kv"><tr><th>Programme</th><td class="mono">${fmtDb(D.inDbu)} tone, +${D.burst} dB burst 0.25–0.6 s</td></tr><tr><th>Peak GR</th><td class="mono">${mx.toFixed(1)} dB</td></tr><tr><th>Limiter attack</th><td class="mono">R42 220 Ω × C33 2.2 µF = ${(LIM_ATT*1000).toFixed(2)} ms</td></tr><tr><th>Limiter release</th><td class="mono">R43 1 MΩ × C33 2.2 µF = ${LIM_REL.toFixed(1)} s</td></tr><tr><th>Recovered (&lt; 0.5 dB GR)</th><td class="mono">${tEnd?SIM.fmtT(tEnd):'not within this second'}</td></tr></table><p class="small">This card's second is about envelopes, not cycles: zoom to 1 s to watch the burst hit, the gain reduction grab within half a millisecond, and the slow 2.2 s limiter release still recovering when the second ends.</p>`; }
const lessons=[
  {title:'The card', auto:true, check:()=>true, body:'<p>No manual survives. The 1995 functional drawing <b>M8207F01.DWG</b> describes it: a DA compressor with SENSITIVITY, a GR (gain-reduction) element, LIMIT CONTROL (THRESHOLD, RELEASE), COMPRESSOR CONTROL (THRESHOLD, SLOPE, RELEASE) and MAKE-UP. The schematic puts a DBX 2151 VCA in the GR element. Set the Zoom window to <b>1 s</b>.</p>'},
  {title:'1 · Watch the burst', check:()=>SIM.win>=0.99, hint:'Zoom window → 1 s (whole).', body:'<p>The test programme is a tone with a +10 dB burst from 0.25 to 0.6 s. In the Timeline, watch the gain-reduction lane.</p><p><b>Goal:</b> zoom to 1 s.</p>'},
  {title:'2 · Compressor only', check:()=>D.comp&&!D.lim, hint:'Untick “limiter”.', body:'<p>Take the limiter out of the study. The compressor reduces gain smoothly by (level − threshold) × (1 − 1/ratio).</p><p><b>Goal:</b> compressor in, limiter out.</p>'},
  {title:'3 · Steeper slope', check:()=>ratio()>=6, hint:'Click the right half of the SLOPE trim (front edge, R68) a few times.', body:'<p>Raise SLOPE until the ratio passes 6 : 1. The burst is pressed nearly flat.</p><p><b>Goal:</b> ratio ≥ 6 : 1.</p>'},
  {title:'4 · The limiter\'s long tail', check:()=>D.lim&&!D.comp, hint:'Tick limiter, untick compressor.', body:'<p>Now the limiter alone. It grabs within 0.48 ms (R42 220 Ω into C33 2.2 µF) and lets go through R43 1 MΩ: a 2.2 s release. After the burst the level stays down for the rest of the second.</p><p><b>Goal:</b> limiter only.</p>'},
  {title:'5 · Make up the loss', check:()=>mkDb()>=6, hint:'Raise the MAKE UP trim (R29).', body:'<p>Compression lowers the average level; MAKE UP restores it after the GR element.</p><p><b>Goal:</b> at least +6 dB make-up.</p>'},
  {title:'Done', auto:true, check:()=>true, body:'<p>See <b>Findings</b>, and the M8208 plugin for the remote-level DA built on the same board.</p>'} ];
const blocks={ w:820, h:290, note:'After M8207F01.DWG (functional) with the parts from XSM8207.DWG.', nodes:{
  in:{x:10,y:30,w:120,h:52,t:'INPUT',s:['0 to +8 dBu'],lv:()=>fmtDb(chain().x),info:'Balanced input, as the M8208.'},
  sn:{x:160,y:30,w:130,h:52,t:'SENSITIVITY',s:['U1 LM833, R13'],lv:()=>fmtDb(chain().s),info:'Input stage and SENSITIVITY pot.'},
  gr:{x:320,y:30,w:150,h:52,t:'GR ELEMENT',s:['U2 DBX 2151 + U3'],lv:()=>'−'+chain().gr.toFixed(1)+' dB',info:'The gain-reduction element: DBX 2151 VCA (OFFSET R16, SYMMETRY R17).'},
  mk:{x:500,y:30,w:140,h:52,t:'MAKE-UP',s:['R29 5K, U4/U5'],lv:()=>fmtDb(chain().out),info:'Make-up gain and the two output amplifiers.'},
  out:{x:670,y:30,w:140,h:52,t:'OUTPUT 1 / 2',s:['0 Ω / 30 Ω'],info:'P1 4/D and 5/E.'},
  lc:{x:320,y:130,w:200,h:60,t:'LIMIT CONTROL',s:['U6 LM837, CR8 1N5711','THRESHOLD R48, C33 2u2'],lv:()=>chain().grl.toFixed(1)+' dB',info:'Peak limiter: attack R42 220 × C33, release R43 1M × C33.'},
  cc:{x:320,y:210,w:200,h:60,t:'COMPRESSOR CONTROL',s:['U7 LM837, U8 LF353, Q1/Q2','THRESHOLD, SLOPE'],lv:()=>chain().grc.toFixed(1)+' dB',info:'Rectifier (1N5711), log pair Q1/Q2 2N3904 and slope stage.'},
  sum:{x:560,y:170,w:90,h:52,t:'Σ',s:['control sum'],info:'The two controls add (the “S” summing node on F01) to drive the GR element.'} },
  edges:[['in','sn'],['sn','gr'],['gr','mk'],['mk','out'],['gr','lc','sense'],['gr','cc'],['lc','sum'],['cc','sum'],['sum','gr','control']] };
const sheets=[
  {name:'M8207F01.DWG — functional', J:F01, note:'“M8207 DA COMPRESSOR FUNCTIONAL”, B 8207-01-001 ISS 0 (1995-05-26), redrawn from the R12 file.'},
  {name:'XSM8207.DWG — schematic', J:XSM, note:'“M8207 COMPRESSOR / LIMITER SCHEMATIC” (1995-12-08). Click a label to see its value.', hl:()=>D.sel?[D.sel]:[]},
  {name:'XS14-278.DWG — the shared master', J:X278, note:'“COMPRESSOR/LIMITER AND REMOTE LEVEL DISTRIBUTION AMPLIFIER SCHEMATIC”: both cards on one sheet, M8208 values in brackets.'} ];
function softHTML(){ const c=chain(); const pts=[]; for(let L=-10;L<=30;L+=1){ const gc=D.comp&&L>cThr()?(L-cThr())*(1-1/ratio()):0, post=L-gc, gl=D.lim?Math.max(0,post-lThr()):0; pts.push([L,L-gc-gl]); }
  const X=v=>40+(v+10)*8, Y=v=>290-(v+10)*6.5; const curve=`<svg viewBox="0 0 380 310" style="width:100%;max-width:380px"><rect x="40" y="30" width="320" height="260" fill="var(--lane)" stroke="var(--line)"/>${[-10,0,10,20,30].map(v=>`<line x1="${X(v)}" y1="30" x2="${X(v)}" y2="290" stroke="var(--grid)"/><text x="${X(v)}" y="304" font-size="9" text-anchor="middle" fill="var(--ink2)">${v}</text><text x="36" y="${Y(v)+3}" font-size="9" text-anchor="end" fill="var(--ink2)">${v}</text>`).join('')}<polyline points="${pts.map(p=>X(p[0])+','+Y(p[1])).join(' ')}" fill="none" stroke="var(--accent)" stroke-width="2.5"/><line x1="${X(-10)}" y1="${Y(-10)}" x2="${X(30)}" y2="${Y(30)}" stroke="var(--ink2)" stroke-dasharray="4 3"/><circle cx="${X(c.s)}" cy="${Y(c.s-c.gr)}" r="5" fill="var(--warn)"/><text x="200" y="20" font-size="11" text-anchor="middle" fill="var(--ink)">static curve: detector level in → after GR (dBu)</text></svg>`;
  return `<div class="grid2">${card('Signal path at the playhead', stageTable(c.stages))}${card('Transfer curve (live)', curve+'<p class="small">The dot is the playhead. Threshold, slope and limit laws '+inf+'; the limiter time constants are from the schematic values.</p>')}</div>${card('Level diagram', levelSVG(c.stages))}`; }
const findings=[
  `<b>The “unknown” card is a compressor/limiter.</b> The README says the function is unknown; <span class="mono">M8207F01.DWG</span> is titled “M8207 DA COMPRESSOR FUNCTIONAL” and <span class="mono">XSM8207.DWG</span> “M8207 COMPRESSOR / LIMITER SCHEMATIC”, with a DBX 2151 GR element, LM837 detectors, an LF353 slope stage and MAKE UP / THRESHOLD trims.`,
  `<b>It was built from a master that was never a product.</b> <span class="mono">XS14-278.DWG</span>: “SA14-278 AS SHOWN ON THIS SCHEMATIC IS NOT USED IN ANY APPLICATION, HOWEVER IT IS USED TO GENERATE M8207 & M8208 SCHEMATICS.” The routed 14-278.PCB holds 192 parts; M8207.PCB 174, M8208.PCB 119.`,
  `<b>The limiter release is very slow.</b> C33 2u2 discharging through R43 1M gives 2.2 s; the attack through R42 220 Ω is about half a millisecond. A broadcast peak limiter with a multi-second recovery behaves more like a level protector than a programme limiter (time constants from the schematic values; their pairing ${inf}).`,
  `<b>Front-panel connectors on a card with no front panel.</b> XSM8207 draws “FRONT PANEL” P2 and P3 near U7D. The 8200 cards sit behind a frame door (8212-020 DA DOOR), so these probably went to an indicator or a test jack ${inf}.`,
  `<b>Functional vs schematic.</b> F01 shows two RELEASE controls; XSM8207 has no trim labelled RELEASE — the releases are fixed by RC values.`,
  `<b>No termination drawing.</b> The folder has no M8207 terminal art; the outputs are the same P1 contacts (4/D, 5/E: 0 Ω and 30 Ω) as the M8208, so its TB8205 options are shown.`,
];
const assume=[`Trim laws (threshold, ratio, make-up, sensitivity ranges) and the compressor attack/release ${inf}.`,`Which 2K/5K trims are compressor THRESHOLD (R56) and SLOPE (R68) ${inf} from their place in the detector chain; R48 THRESHOLD, R29 MAKE UP, R60 OFFSET are labelled on the schematic.`,`The P2/P3 gain-reduction indicator ${inf}.`,`Rear terminals taken from the M8208's TB8205 option.`];
